// 1. Check which input data actually arrived at this node
const incomingItems = $input.all();
let basePayload = {};
if (incomingItems && incomingItems.length > 0) {
  basePayload = incomingItems[0].json;
}

// 2. Access your Google Sheet row directly using standard n8n expression format
// Sheet columns: Mobile Number | Session ID | Reception Number | Department
let sheetRow = {};
try {
  sheetRow = $("Get Google Sheet Row").first().json;
} catch (e) {
  sheetRow = {};
}

// 3. Extract the message text seamlessly based on which path was active
let finalMessage = basePayload["User Message"] || basePayload["text"] || "";
let messageType = basePayload["Message Type"] || (basePayload["text"] ? "audio" : "text");

// 4. Return the consolidated output format your Switch3 node expects
return [{
  json: {
    "Mobile Number": basePayload["Mobile Number"] || sheetRow["Mobile Number"] || "",
    "Routing Destination": basePayload["Routing Destination"] || sheetRow["Routing Destination"] || "",
    "User Message": finalMessage,
    "Message Type": messageType,
    "Session ID": basePayload["Session ID"] || sheetRow["Session ID"] || ""
  }
}];

// 1. Grab incoming data from the trigger node
const inputData = $input.item.json;

// Extract user message safely using brackets for spaces
let userMessage = (inputData["User Message"] || inputData.userMessage || inputData.message || inputData.query || "").trim();

// FIX: Added explicit bracket notation for space-separated "Mobile Number"
let mobileNumber = inputData["Mobile Number"] || inputData.Phone || inputData.phone || inputData.mobile || "";

// Normalize mobile number structure to 92 standard
let cleanMobile = mobileNumber.replace(/[^\d]/g, '');
if (cleanMobile.startsWith('0')) {
    cleanMobile = '92' + cleanMobile.substring(1);
} else if (!cleanMobile.startsWith('92') && cleanMobile.length > 0) {
    cleanMobile = '92' + cleanMobile;
}

// 2. PRODUCTION GUARD: Strict validation for Session ID
let rawSessionId = inputData["Session ID"] || inputData.sessionId || inputData.session_id;
let sessionId = "";

// Force generation if the incoming session is missing, blank, or an explicit null object
if (rawSessionId !== undefined && rawSessionId !== null && String(rawSessionId).trim() !== "" && String(rawSessionId) !== "[null]") {
    sessionId = String(rawSessionId).trim();
} else {
    // Generate clean unique production stamp (Mobile + Date + Timestamp)
    const now = new Date();

    // Format: YYYYMMDD
    const year = now.getFullYear();
    const month = String(now.getMonth() + 1).padStart(2, '0');
    const day = String(now.getDate()).padStart(2, '0');
    const dateStamp = `${year}${month}${day}`;

    // Format: HHMMSS
    const hours = String(now.getHours()).padStart(2, '0');
    const minutes = String(now.getMinutes()).padStart(2, '0');
    const seconds = String(now.getSeconds()).padStart(2, '0');
    const timeStamp = `${hours}${minutes}${seconds}`;

    // Use the cleaned mobile number or fallback gracefully
    const trackingMobile = cleanMobile || "NO_PHONE";

    sessionId = `${trackingMobile}-${dateStamp}-${timeStamp}`;
}

// 3. Regular Expression Definitions for Routing
const greetingRegex = /^(hi|hello|aoa|salaam|hey|assalam|hi there)$/i;
const bookingOptions = /^[1-3]$/; // Matches 1, 2, or 3
const supportOptions = /^[4-6]$/; // Matches 4, 5, or 6

let route = "show_menu"; // Default fallback route

// 4. ROUTING MATRIX ENGINE
if (greetingRegex.test(userMessage)) {
    route = "show_menu";
} else if (bookingOptions.test(userMessage)) {
    route = "reception_123"; 
} else if (supportOptions.test(userMessage)) {
    route = "reception_456"; 
} else {
    route = "show_menu";
}

// 5. Clean Outbound Data Payload
return {
    json: {
        route: route,
        sessionId: sessionId, 
        mobileNumber: cleanMobile, // <--- WILL NOW POPULATE CORRECTLY
        userMessage: userMessage
    }
};

// 1. Automatically grab data from whichever node is connected right before this one
const incomingData = $input.first().json;

// 2. Safely extract the text string (handles 'output', 'chatInput', or 'value')
let rawText = incomingData.output || incomingData.chatInput || incomingData.value || "";

let matchedDepartment = "";
const validDays = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"];
let finalDaysState = {
    Monday: "", Tuesday: "", Wednesday: "", Thursday: "", Friday: "", Saturday: "", Sunday: ""
};

if (rawText) {
    // Normalize literal '\n' text strings into real line breaks
    rawText = rawText.replace(/\\n/g, '\n');

    // 3. Split into lines and parse line by line
    const lines = rawText.split('\n');
    for (const line of lines) {
        const cleanLine = line.trim();

        // Extract Department Name
        if (cleanLine.toLowerCase().includes('department:')) {
            matchedDepartment = cleanLine.split(':')[1].trim();
        }

        // Extract Availability Days
        for (let day of validDays) {
            if (cleanLine.toLowerCase().startsWith(day.toLowerCase() + ':')) {
                const value = cleanLine.split(':')[1].trim();
                if (value.toLowerCase() === "not available") {
                    finalDaysState[day] = "Not Available";
                } else {
                    finalDaysState[day] = "";
                }
            }
        }
    }
}

// 4. Output the cleanly parsed department and all 7 day variables dynamically
return {
    json: {
        Department: matchedDepartment,
        Monday: finalDaysState["Monday"],
        Tuesday: finalDaysState["Tuesday"],
        Wednesday: finalDaysState["Wednesday"],
        Thursday: finalDaysState["Thursday"],
        Friday: finalDaysState["Friday"],
        Saturday: finalDaysState["Saturday"],
        Sunday: finalDaysState["Sunday"]
    }
};

