// 1. Get the current day name dynamically (e.g., "Monday", "Tuesday")
const daysOfWeek = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];
const todayIndex = new Date().getDay(); 
const todayName = daysOfWeek[todayIndex];

const items = $input.all();
const updatedItems = [];

// 2. Loop through every doctor record fetched from the sheet
for (const item of items) {
    let row = { ...item.json };

    // Check if TODAY's column specifically is marked as 'Not Available'
    if (row[todayName] && row[todayName].toLowerCase().trim() === 'not available') {
        row[todayName] = ""; // Reset ONLY today's cell to blank

        updatedItems.push({ json: row }); // Only pass forward rows that need updating
    }
}

// 3. Forward only the modified rows to avoid wasting Google Sheet API quota
return updatedItems;

